// regra — o alerta é o produto percebido: lido em dois minutos, prioridades na ordem do
//   Fopa-v2/05-Arquitetura/8 Orquestrador.md:30-42 (P1 … P6) e, por último, o sinal do Jev.
// regra — "NADA VISTO" ≠ "NADA A FAZER": scripts/20_monitor.py:408-435 e :495-505 (ADR-007).
// regra — a linguagem visual do painel (scripts/fopa/painel.py:26-70 e :370; web/design/README.md):
//   tokens, tabela com cabeçalho --ink, vermelho só para defeito, números em mono. E-mail = HTML
//   estático: tabelas simples, estilo inline, nenhum JS.
const J = $('Janela do alerta').first().json;
const P1 = $('P1 Sessão em até 7 dias').first().json;
const P2 = $('P2 Retificações').first().json;
const P3 = $('P3 Novas desde ontem').first().json;
const P5 = $('P5 Revisões abertas').first().json;
const P6 = $('P6 Extraídas que pedem olho humano').first().json;
const JEV = $('Jev: o filtro pode ter errado').first().json;
const R = $('Rodapé: coleta, custo, falhas').first().json;

const C = { ink: '#11243D', ink2: '#1B3454', paper: '#FFFFFF', surf2: '#F4F2EE', line: '#DCD7CC',
  muted: '#55606E', red: '#B23A32', reds: '#F6E4E2', teal: '#1D6F63', teals: '#DDEAE7',
  amber: '#8A6A18', ambers: '#F5EBD2' };
const SANS = "'IBM Plex Sans',system-ui,-apple-system,'Segoe UI',sans-serif";
const MONO = "'IBM Plex Mono',ui-monospace,Consolas,monospace";
const MAX = 15;   // linhas por seção; o resto fica no site (o alerta tem de caber em dois minutos)

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const num = (n) => Number(n) || 0;
const milhar = (n) => String(Math.trunc(num(n))).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const brl = (v) => { const [i, d] = num(v).toFixed(2).split('.'); return 'R$ ' + milhar(i) + ',' + d; };
const plural = (n, um, varios) => milhar(n) + ' ' + (num(n) === 1 ? um : varios);
const itens = (p) => (p && Array.isArray(p.itens)) ? p.itens : [];

// URLs públicas, com ou sem barra no fim. Dentro do compose FOPA_SITE_URL é o hostname interno
// (http://fopa-api:8080), que não abre fora do Docker: só vale se parecer público.
const semBarra = (u) => String(u || '').trim().replace(/\/+$/, '');
const publica = (u) => {
  const s = semBarra(u);
  if (!/^https?:\/\/[^/]+/i.test(s)) return '';
  const host = s.replace(/^https?:\/\//i, '').split(/[/:]/)[0];
  return (host === 'localhost' || host.includes('.')) ? s : '';
};
const siteEnv = publica($env.FOPA_SITE_PUBLIC_URL) || publica($env.FOPA_SITE_URL);
const SITE = siteEnv || 'http://localhost:8080';
const N8N = semBarra($env.N8N_EDITOR_BASE_URL || $env.WEBHOOK_URL);
const linkLic = (slug) => SITE + '/licitacao/' + encodeURIComponent(String(slug || ''));
// A fila de revisão do site (web/src/paginas/Revisao.tsx): ?aba=escopo abre a aba do rótulo de escopo.
const linkRevisao = (aba) => SITE + '/revisao' + (aba ? '?aba=' + encodeURIComponent(aba) : '');
const link = (url, txt) => `<a href="${esc(url)}" style="color:${C.ink2}">${txt}</a>`;
const linkExec = N8N ? N8N + '/workflow/' + $workflow.id + '/executions/' + $execution.id : '';

// ---- peças visuais: o painel em estilo inline
const P = (h) => `<p style="margin:0 0 8px">${h}</p>`;
const marca = (txt, tom) => {
  const [cor, fundo] = ({ ok: [C.teal, C.teals], rev: [C.amber, C.ambers], def: [C.red, C.reds] })[tom] || [C.muted, C.surf2];
  return `<span style="display:inline-block;margin:0 4px 2px 0;font-family:${MONO};font-size:11px;line-height:1.5;`
    + `padding:0 6px;border-radius:4px;border:1px solid ${cor};color:${cor};background:${fundo};white-space:nowrap">${esc(txt)}</span>`;
};
const th = (t) => `<th align="left" style="background:${C.ink};color:${C.paper};text-align:left;font-size:11.5px;`
  + `letter-spacing:.06em;text-transform:uppercase;padding:9px 14px;font-weight:600">${t}</th>`;
const td = (h, largura) => `<td valign="top" style="padding:9px 14px;border-top:1px solid ${C.line};vertical-align:top;`
  + `font-size:13px${largura ? ';width:' + largura : ''}">${h}</td>`;
const tabela = (cab, linhas) => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" `
  + `style="width:100%;border-collapse:collapse;border:1px solid ${C.line}"><tr>${cab.map(th).join('')}</tr>`
  + linhas.map((l) => `<tr>${l}</tr>`).join('') + '</table>';
const licitacao = (x, extra) => `<a href="${esc(linkLic(x.slug))}" style="color:${C.ink2};font-weight:600;text-decoration:none">`
  + `${esc(x.local || x.controle)}</a><br><span style="font-size:12px;color:${C.muted}">`
  + `${esc([x.modalidade, x.controle].filter(Boolean).join(' · '))}</span>${extra || ''}`;
const objeto = (x) => x.objeto ? `<br><span style="font-size:12.5px;color:${C.ink2}">${esc(x.objeto)}`
  + `${String(x.objeto).length >= 160 ? '…' : ''}</span>` : '';
// Prazo como o painel (scripts/fopa/painel.py:370): até 7 dias vermelho, 8 a 20 âmbar, "N dia(s)" + data.
const prazo = (x) => {
  if (x.dias === null || x.dias === undefined) {
    return `<b style="font-family:${MONO}">—</b><br><span style="font-size:12px;color:${C.muted}">prazo não informado</span>`;
  }
  const d = num(x.dias);
  if (d < 0) {
    return `<b style="font-family:${MONO};font-size:15px">encerrado</b><br>`
      + `<span style="font-size:12px;color:${C.muted}">há ${plural(-d, 'dia', 'dias')}</span>`;
  }
  const cor = d <= 7 ? C.red : d <= 20 ? C.amber : C.ink;
  return `<b style="font-family:${MONO};font-size:15px;color:${cor};font-variant-numeric:tabular-nums;white-space:nowrap">`
    + `${milhar(d)} dia${d === 1 ? '' : 's'}</b><br>`
    + `<span style="font-size:12px;color:${C.muted};white-space:nowrap">${esc(x.sessao || '')}</span>`;
};
const vazio = (h) => `<p style="margin:0;padding:11px 14px;border:1px solid ${C.line};border-radius:8px;`
  + `color:${C.muted};font-size:13px">${h}</p>`;
// O resto fica no site: no painel, ou na fila de revisão quando é lá que se decide.
const mais = (total, mostrados, url, onde) => num(total) > mostrados
  ? `<p style="margin:6px 0 0;font-size:12.5px;color:${C.muted}">e mais ${milhar(num(total) - mostrados)} `
    + (url ? 'na ' + link(url, onde) : 'no ' + link(SITE + '/', 'painel')) + '.</p>' : '';
const secao = (rotulo, titulo, sub, corpo) => '<tr><td style="padding:24px 0 0">'
  + `<p style="font-family:${MONO};font-size:12px;letter-spacing:.16em;text-transform:uppercase;color:${C.muted};margin:0 0 4px">${rotulo}</p>`
  + `<h2 style="font-size:18px;font-weight:600;margin:0 0 4px;line-height:1.3;color:${C.ink}">${titulo}</h2>`
  + (sub ? `<p style="color:${C.muted};margin:0 0 10px;font-size:13.5px">${sub}</p>` : '')
  + corpo + '</td></tr>';
const caixa = (h, cor, fundo) => `<div style="border:1px solid ${cor};border-left:4px solid ${cor};background:${fundo};`
  + `border-radius:8px;padding:12px 16px;color:${cor};font-size:14px">${h}</div>`;
const q5 = (x) => {
  if (!x.extraida) return marca('sem extração', 'neutro');
  if (x.q5 === 'APROVADO') return marca('conferido', 'ok');
  if (x.q5 === 'REVISAR') return marca('revisar', 'rev');
  if (x.q5 === 'REPROVADO') return marca('reprovado', 'def');
  return marca('sem veredito', 'neutro');
};
const desde = esc(J.desde_fmt);

// ---- P1 · sessão em até 7 dias (lance ainda não definido = Q5 não conferida)
const l1 = itens(P1).slice(0, MAX).map((x) => td(prazo(x), '118px') + td(licitacao(x))
  + td(q5(x) + (x.injecao_suspeita ? marca('injeção suspeita', 'def') : '')
       + (x.revisao_pendente ? marca('revisão aberta', 'rev') : '')));
const s1 = secao('P1 · sessão em até 7 dias', 'Sessão nos próximos 7 dias',
  num(P1.n) ? `${plural(P1.n, 'licitação', 'licitações')} com sessão até ${esc(J.limite_fmt)}; `
    + `<b>${milhar(P1.sem_lance)}</b> ainda sem o valor mínimo (Q5) conferido — é o dado do lance.` : '',
  num(P1.n) ? tabela(['Sessão', 'Licitação', 'Valor mínimo (Q5)'], l1) + mais(P1.n, l1.length)
            : vazio('Nenhuma sessão nos próximos 7 dias.'));

// ---- P2 · retificação
const l2 = itens(P2).slice(0, MAX).map((x) => td(prazo(x), '118px') + td(licitacao(x))
  + td(esc(x.motivo || 'retificada') + `<br><span style="font-size:12px;color:${C.muted}">${esc(x.quando)}</span>`)
  + td(x.ja_analisada ? marca('já analisada: Q1 pode ter mudado', 'rev') : marca('ainda não analisada', 'neutro')));
const s2 = secao('P2 · retificação', 'Retificações detectadas',
  num(P2.n) ? 'O PNCP mudou a licitação depois que a lemos: ela volta para a fila e é lida de novo. '
    + 'Até lá, a data e o valor do relatório podem estar velhos.' : '',
  num(P2.n) ? tabela(['Sessão', 'Licitação', 'O que mudou', 'Antes'], l2) + mais(P2.n, l2.length)
            : vazio(`Nenhuma retificação desde ${desde}.`));

// ---- P3 · novas
const l3 = itens(P3).slice(0, MAX).map((x) => td(prazo(x), '118px') + td(licitacao(x, objeto(x)))
  + td(marca(x.o_que, x.publicada ? 'ok' : 'neutro')
       + (x.publicada && num(x.respondidas) ? `<br><span style="font-family:${MONO};font-size:12px">`
          + `${milhar(x.ancoradas)}/${milhar(x.respondidas)} ancoradas</span>` : '')));
const s3 = secao('P3 · novas', 'Novas desde ' + desde,
  num(P3.n) ? `${plural(P3.novas, 'licitação de folha encontrada', 'licitações de folha encontradas')} no PNCP · `
    + `${plural(P3.publicadas, 'extraída e publicada', 'extraídas e publicadas')}.` : '',
  num(P3.n) ? tabela(['Sessão', 'Licitação', 'O que aconteceu'], l3) + mais(P3.n, l3.length)
            : vazio(`Nenhuma licitação nova de folha nem publicação desde ${desde}.`));

// ---- P4 · resultados: não coletado (fixo, plano §5 W40)
const s4 = secao('P4 · resultados', 'Resultados publicados (vencedor e valor)', '',
  vazio('<b>Não coletado.</b> O FOPA ainda não lê resultados no PNCP: esta seção fica vazia por construção, '
    + 'não por falta de resultado.'));

// ---- P5 · revisão humana
const l5 = itens(P5).slice(0, MAX).map((x) => td(prazo(x), '118px') + td(licitacao(x))
  + td(`<b style="font-family:${MONO}">${milhar(x.abertas)}</b> <span style="font-size:12px;color:${C.muted}">`
       + `aberta${num(x.abertas) === 1 ? '' : 's'} desde ${esc(x.aberta_desde)}</span><br>`
       + `<span style="font-family:${MONO};font-size:12px">${esc(x.perguntas)}</span>`)
  + td(`<span style="font-size:12.5px">${esc(x.motivo || '')}</span>`));
const s5 = secao('P5 · revisão humana', 'Aguardando decisão humana',
  num(P5.n) ? `${plural(P5.perguntas_abertas, 'resposta marcada', 'respostas marcadas')} para revisar em `
    + `${plural(P5.n, 'licitação', 'licitações')}` + (num(P5.novas) ? ` (${milhar(P5.novas)} desde ${desde})` : '')
    + '. Decidir na ' + link(linkRevisao(), 'fila de revisão') + ' tira a linha daqui no alerta seguinte.' : '',
  num(P5.n) ? tabela(['Sessão', 'Licitação', 'Abertas', 'Motivo'], l5)
              + mais(P5.n, l5.length, linkRevisao(), 'fila de revisão')
            : vazio('Nenhuma revisão aberta.'));

// ---- P6 · olho humano (o que o verificador marcou, sessão ainda aberta)
const sinais6 = (x) => (x.injecao ? marca('injeção suspeita', 'def') : '')
  + (num(x.reprovadas) ? marca(plural(x.reprovadas, 'reprovada', 'reprovadas'), 'def') : '')
  + (num(x.conflitos) ? marca(plural(x.conflitos, 'conflito', 'conflitos'), 'rev') : '')
  + (num(x.alertas) ? marca(plural(x.alertas, 'alerta de regra', 'alertas de regra'), 'rev') : '')
  + (x.degradada ? marca('leitura degradada', 'rev') : '') + (x.nova ? marca('nova', 'neutro') : '')
  + (x.alerta1 ? `<br><span style="font-size:12px;color:${C.muted}">${esc(x.alerta1)}`
     + `${String(x.alerta1).length >= 180 ? '…' : ''}</span>` : '');
const l6 = itens(P6).slice(0, 10).map((x) => td(prazo(x), '118px') + td(licitacao(x)) + td(sinais6(x)));
const s6 = secao('P6 · olho humano', 'Extraídas que pedem olho humano',
  num(P6.n) ? `Sessão ainda aberta e o verificador marcou algo: ${milhar(P6.injecao)} com injeção suspeita · `
    + `${milhar(P6.reprovadas)} com reprovada · ${milhar(P6.conflito)} com conflito entre documentos · `
    + `${milhar(P6.alerta)} com alerta de regra. As mais graves primeiro.` : '',
  num(P6.n) ? tabela(['Sessão', 'Licitação', 'O que o verificador marcou'], l6) + mais(P6.n, l6.length)
            : vazio('Nenhuma extraída com sessão aberta tem injeção, reprovada, conflito ou alerta de regra.'));

// ---- Jev · o filtro pode ter errado (sinal, não decisão — T25)
const lj = itens(JEV).slice(0, 10).map((x) => td(prazo(x), '118px') + td(licitacao(x, objeto(x)))
  + td(marca(x.regra === 'dentro' ? 'regra: é folha' : 'regra: não é folha', 'neutro')
       + `<br><span style="font-size:12px;color:${C.muted}">Jev: P(folha) = </span>`
       + `<b style="font-family:${MONO}">${esc(String(x.p_sim).replace('.', ','))}</b>`));
const sj = secao('Sinal · Jev', 'O filtro pode ter errado aqui',
  num(JEV.n) ? `<b>Sinal, não decisão.</b> O Jev (segundo sinal) discorda da regra de escopo com convicção em `
    + `${plural(JEV.n, 'licitação', 'licitações')}`
    + (num(JEV.abertas) < num(JEV.n) ? ` (${milhar(JEV.abertas)} com sessão aberta)` : '')
    + '. A regra continua valendo: nada entra nem sai da fila sem um rótulo humano ('
    + link(linkRevisao('escopo'), 'aba escopo da revisão') + ').' : '',
  num(JEV.n) ? tabela(['Sessão', 'Licitação', 'Regra × Jev'], lj)
               + mais(JEV.n, lj.length, linkRevisao('escopo'), 'aba escopo da revisão')
             : vazio('Nenhuma candidata do Jev sem rótulo humano: o filtro de escopo não foi contestado.'));

// ---- NADA VISTO × nada a fazer (a coleta viu o PNCP?)
const col = R.coleta || null;
let nadaVisto = null;
if (!col) nadaVisto = 'nenhuma coleta do PNCP registrada até agora (o W01 ainda não rodou)';
else if (!col.na_janela) nadaVisto = `nenhuma coleta do PNCP desde ${J.desde_fmt} (a última foi em ${col.quando})`;
else if (col.cego === true) nadaVisto = `a coleta de ${col.quando} foi cega: nenhuma busca no PNCP funcionou`;
const quem = col ? (col.script_legado ? col.script_legado + ', v2' : col.quem) : '';
const linhaColeta = nadaVisto
  ? `<b style="color:${C.red}">NADA VISTO</b> — ${esc(nadaVisto)}.`
  : `última coleta do PNCP em ${esc(col.quando)} (${esc(quem)})`
    + (col.cobertura !== null && col.cobertura !== undefined ? `, cobertura média ${esc(String(col.cobertura).replace('.', ','))}%` : '')
    + '.' + (num(col.termos_falhos) ? ` ${milhar(col.termos_falhos)} de ${milhar(col.termos)} termos falharam: `
      + 'o que vem acima é piso, não total.' : '');
const caixaVisto = nadaVisto ? '<tr><td style="padding:18px 0 0">' + caixa(`<b>NADA VISTO</b> — ${esc(nadaVisto)}. `
  + 'Isto <b>não</b> é “nada a fazer”: é “não consegui olhar”. A falta de licitação nova neste e-mail '
  + 'não quer dizer que não houve.', C.red, C.reds) + '</td></tr>' : '';
const w70 = R.w70 || null;
const cw = (w70 && w70.contadores) || {};
const linhaW70 = !w70 ? 'o W70 (semanal) ainda não rodou.'
  : `última conferência do W70 em ${esc(w70.quando)}: ${milhar(cw.conferidas)} conferidas, `
    + `${milhar(cw.retificadas)} retificadas, ${milhar(cw.nao_conferidas)} sem resposta do PNCP`
    + (num(cw.fora_do_limite) ? `, ${milhar(cw.fora_do_limite)} ficaram fora do limite da rodada` : '')
    + (w70.cego ? ` — <b style="color:${C.red}">CEGA</b>` : '') + '.';
const custo = num(R.chamadas) === 0 ? 'nenhuma chamada de modelo (R$ 0,00)'
  : brl(R.custo_brl) + (num(R.sem_preco) ? ` + ${plural(R.sem_preco, 'chamada', 'chamadas')} com preço não configurado` : '');

// ---- cabeçalho, números e rodapé
const cabecalho = '<tr><td style="padding:0">'
  + `<p style="font-family:${MONO};font-size:12px;letter-spacing:.16em;text-transform:uppercase;color:${C.red};margin:0 0 8px">Folha de pagamento · setor público</p>`
  + `<h1 style="font-size:26px;font-weight:600;margin:0 0 6px;line-height:1.2;color:${C.ink}">Alerta diário · ${esc(J.hoje_fmt)}</h1>`
  + `<p style="color:${C.muted};margin:0;font-size:14.5px">Ordenado por <b>urgência</b>: o que fecha primeiro vem antes. `
  + `Cobre desde ${desde}. Cada licitação abre no site com as 17 respostas e a página de cada evidência.</p></td></tr>`;
const tile = (n, rotulo, al) => '<td valign="top" style="width:33%;padding:0 8px 8px 0">'
  + `<div style="border:1px solid ${C.line};border-radius:10px;padding:12px 14px">`
  + `<b style="display:block;font-family:${MONO};font-size:22px;font-variant-numeric:tabular-nums;color:${al ? C.red : C.ink}">${milhar(n)}</b>`
  + `<span style="font-size:12.5px;color:${C.muted}">${rotulo}</span></div></td>`;
const tiles = '<tr><td style="padding:18px 0 0"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" '
  + 'style="width:100%;border-collapse:collapse">'
  + `<tr>${tile(P1.n, 'sessões em até 7 dias', num(P1.n) > 0)}${tile(P2.n, 'retificadas', false)}${tile(P3.novas, 'novas de folha', false)}</tr>`
  + `<tr>${tile(P5.perguntas_abertas, 'respostas para revisar', num(P5.perguntas_abertas) > 0)}`
  + `${tile(P6.n, 'extraídas pedem olho humano', num(P6.injecao) + num(P6.reprovadas) > 0)}`
  + `${tile(JEV.n, 'filtro contestado (Jev)', false)}</tr></table></td></tr>`;
const execucao = linkExec ? `<a href="${esc(linkExec)}" style="color:${C.ink2}">execução ${esc($execution.id)}</a>`
  : `execução ${esc($execution.id)}`;
const rodape = '<tr><td style="padding:26px 0 0">'
  + `<div style="border-top:1px solid ${C.line};padding-top:14px;color:${C.muted};font-size:12.5px">`
  + P(`Desde ${desde}: <b style="color:${C.ink}">${milhar(R.processadas)}</b> processada${num(R.processadas) === 1 ? '' : 's'} · `
    + `<b style="color:${num(R.falharam) ? C.red : C.ink}">${milhar(R.falharam)}</b> ${num(R.falharam) === 1 ? 'falhou' : 'falharam'} `
    + `(entraram em estado de erro) · ${plural(R.erros_fluxo, 'erro de fluxo', 'erros de fluxo')} (W90) · `
    + `${plural(R.emails_falhos, 'e-mail falhou', 'e-mails falharam')} · custo ${esc(custo)} · `
    + `provedor vigente: <b style="color:${C.ink}">${esc(R.provedor || '—')}</b>.`)
  + P(`Coleta: ${linhaColeta} Retificações: ${linhaW70}`)
  + P(`Gerado em ${esc(J.agora_fmt)} pelo W40 · ${execucao} · só licitações de ${esc(J.ano_minimo)} em diante (ADR-015) · `
    + 'Fonte: PNCP — dados abertos, Lei 14.133/2021 art. 54 · Nenhum dado pessoal é armazenado.')
  + (siteEnv ? '' : P(`Links do site pela URL local padrão (${esc(SITE)}): defina FOPA_SITE_PUBLIC_URL no fopa-n8n.`))
  + '</div></td></tr>';

// ---- dia sem nada relevante: e-mail curto, nunca silêncio
const relevante = [P1.n, P2.n, P3.n, P5.n, P6.n, JEV.n].some((n) => num(n) > 0);
const linhaP4 = '<tr><td style="padding:12px 0 0">'
  + vazio('<b>P4 · resultados:</b> não coletado — o FOPA ainda não lê vencedor e valor no PNCP.') + '</td></tr>';
const curto = (nadaVisto
  ? caixaVisto + '<tr><td style="padding:12px 0 0">' + vazio('Nas licitações que já conhecemos não há nada pendente: '
    + 'nenhuma sessão em até 7 dias, retificação, revisão aberta, alerta do verificador ou contestação do Jev.') + '</td></tr>'
  : '<tr><td style="padding:18px 0 0">' + caixa(`<b>NADA A FAZER</b> — desde ${desde}: nenhuma sessão nos próximos `
    + '7 dias, nada novo, retificado, para revisar, com alerta do verificador ou contestado pelo Jev. '
    + 'A coleta do PNCP rodou e viu o mercado.', C.teal, C.teals) + '</td></tr>') + linhaP4;

// ---- assunto: o que importa primeiro, curto
const partes = [];
if (num(P1.n)) partes.push(plural(P1.n, 'sessão', 'sessões') + ' em até 7 dias');
if (num(P2.n)) partes.push(plural(P2.n, 'retificada', 'retificadas'));
if (num(P3.novas)) partes.push(plural(P3.novas, 'nova', 'novas'));
if (num(P5.perguntas_abertas)) partes.push(milhar(P5.perguntas_abertas) + ' para revisar');
if (num(P6.injecao)) partes.push(milhar(P6.injecao) + ' com injeção suspeita');
if (num(JEV.n)) partes.push(milhar(JEV.n) + ' para rotular (Jev)');
if (!partes.length && num(P6.n)) partes.push(plural(P6.n, 'extraída pede olho', 'extraídas pedem olho'));
const assunto = '[FOPA] Alerta ' + String(J.hoje_fmt || '').slice(0, 5) + (nadaVisto ? ' · NADA VISTO' : '')
  + (relevante ? ' · ' + partes.slice(0, 4).join(' · ') : ' · nada novo');

const corpo = relevante ? cabecalho + caixaVisto + tiles + s1 + s2 + s3 + s4 + s5 + s6 + sj + rodape
                        : cabecalho + curto + rodape;
const html = '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8">'
  + '<meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light">'
  + `<title>${esc(assunto)}</title></head>`
  + `<body style="margin:0;padding:0;background:${C.paper};color:${C.ink};font-family:${SANS};font-size:15px;line-height:1.55">`
  + `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:collapse;background:${C.paper}">`
  + '<tr><td style="padding:28px 16px 40px">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;max-width:760px;margin:0 auto;border-collapse:collapse">'
  + corpo + '</table></td></tr></table></body></html>';

return [{ json: { assunto, corpo_html: html, contadores: {
  janela_desde: J.desde, p1: num(P1.n), p1_sem_valor_minimo: num(P1.sem_lance), p2: num(P2.n),
  p3_novas: num(P3.novas), p3_publicadas: num(P3.publicadas), p4: 'não coletado',
  p5_licitacoes: num(P5.n), p5_respostas: num(P5.perguntas_abertas), p6: num(P6.n), p6_injecao: num(P6.injecao),
  jev_candidatas: num(JEV.n), nada_novo: !relevante, nada_visto: nadaVisto, site: SITE,
} } }];
